sp_widget.client_script:
function tripRequestController($scope) {
	var c = this;
	c.data = c.data || {};
	c.data.travelType = c.data.travelType || "solo";
	c.data.destinationPackage = c.data.destinationPackage || "silver";
	c.submitting = false;
	c.errorMsg = "";
	c.weather = null;
	c.weatherLoading = false;
	c.weatherError = "";

	var WEATHER_CODES = {0:"Clear sky",1:"Mainly clear",2:"Partly cloudy",3:"Overcast",45:"Fog",48:"Depositing rime fog",51:"Light drizzle",53:"Moderate drizzle",55:"Dense drizzle",56:"Light freezing drizzle",57:"Dense freezing drizzle",61:"Slight rain",63:"Moderate rain",65:"Heavy rain",66:"Light freezing rain",67:"Heavy freezing rain",71:"Slight snow fall",73:"Moderate snow fall",75:"Heavy snow fall",77:"Snow grains",80:"Slight rain showers",81:"Moderate rain showers",82:"Violent rain showers",85:"Slight snow showers",86:"Heavy snow showers",95:"Thunderstorm",96:"Thunderstorm with slight hail",99:"Thunderstorm with heavy hail"};

	c.onDestinationChange = function() {
		c.weather = null;
		c.weatherError = "";
		c.data.weatherSummary = "";
		var locId = c.data.destinationId;
		if (!locId) { return; }
		var loc = null;
		var list = ($scope.data && $scope.data.locations) || [];
		for (var i = 0; i < list.length; i++) {
			if (list[i].sys_id === locId) { loc = list[i]; break; }
		}
		if (!loc) { return; }
		if (!loc.latitude || !loc.longitude) {
			c.weatherError = "Weather data isn't available for this location.";
			return;
		}
		c.weatherLoading = true;
		fetch("https://api.open-meteo.com/v1/forecast?latitude=" + loc.latitude + "&longitude=" + loc.longitude + "&current_weather=true")
			.then(function(r) { return r.json(); })
			.then(function(wx) {
				c.weatherLoading = false;
				if (wx.current_weather) {
					var code = wx.current_weather.weathercode;
					c.weather = {
						tempC: Math.round(wx.current_weather.temperature),
						description: WEATHER_CODES[code] || ("Code " + code),
						place: loc.label
					};
					c.data.weatherSummary = c.weather.tempC + "C, " + c.weather.description + " (" + c.weather.place + ")";
				} else {
					c.weatherError = "Weather data unavailable.";
				}
				$scope.$applyAsync();
			})
			.catch(function() {
				c.weatherLoading = false;
				c.weatherError = "Unable to fetch weather right now.";
				$scope.$applyAsync();
			});
	};

	c.submit = function() {
		c.errorMsg = "";
		if (!c.data.destinationId || !c.data.startDate || !c.data.endDate || !c.data.buddyId || !c.data.emergencyName || !c.data.emergencyPhone) {
			c.errorMsg = "Please fill in all required fields, including a travel buddy.";
			return;
		}
		c.submitting = true;
		c.data.action = "submit";
		c.server.update().then(function(response) {
			c.submitting = false;
			if (response.data.error) {
				c.errorMsg = response.data.error;
			}
		});
	};
}

sp_widget.script:
(function(data, input) {
	data.submitted = false;

	// Always provide the list of available travel buddies (active users holding the Buddy role).
	// Query sys_user directly (public-readable) via its "roles" pseudo-field rather than
	// sys_user_has_role, which is ACL-restricted for ordinary logged-in travelers.
	data.buddies = [];
	var BUDDY_ROLE_SYS_ID = "2630792e47d2c31089b4a22f316d4379";
	var buddyGr = new GlideRecord("sys_user");
	buddyGr.addQuery("active", true);
	buddyGr.addQuery("roles", BUDDY_ROLE_SYS_ID);
	buddyGr.query();
	while (buddyGr.next()) {
		data.buddies.push({
			sys_id: buddyGr.getUniqueValue(),
			name: buddyGr.getValue("name"),
			email: buddyGr.getValue("email")
		});
	}

	// Destination is a true reference to cmn_location - populate the picker from the location catalog
	// (including lat/long so the client can fetch weather without a separate geocoding call).
	data.locations = [];
	var locGr = new GlideRecord("cmn_location");
	locGr.orderBy("name");
	locGr.query();
	while (locGr.next()) {
		var city = locGr.getValue("city");
		var country = locGr.getValue("country");
		var label = (city && country) ? (city + ", " + country) : (locGr.getValue("name") || city || country);
		data.locations.push({
			sys_id: locGr.getUniqueValue(),
			label: label,
			latitude: locGr.getValue("latitude"),
			longitude: locGr.getValue("longitude")
		});
	}

	if (!input || input.action !== "submit") { return; }

	var destinationId = input.destinationId;
	var startDate = input.startDate;
	var endDate = input.endDate;
	var buddyId = input.buddyId;
	var emergencyName = (input.emergencyName || "").trim();
	var emergencyPhone = (input.emergencyPhone || "").trim();

	if (!destinationId || !startDate || !endDate || !buddyId || !emergencyName || !emergencyPhone) {
		data.error = "Please fill in all required fields, including a travel buddy.";
		return;
	}
	if (!gs.getUserID()) {
		data.error = "You must be logged in to request a trip.";
		return;
	}

	var loc = new GlideRecord("cmn_location");
	if (!loc.get(destinationId)) {
		data.error = "Please select a valid destination.";
		return;
	}

	var trip = new GlideRecord("x_travel_buddy_app_trip_request");
	trip.initialize();
	trip.u_traveler = gs.getUserID();
	trip.u_destination = destinationId;
	trip.start_time = startDate + " 00:00:00";
	trip.end_time = endDate + " 00:00:00";
	trip.u_travel_type = input.travelType || "solo";
	trip.u_group_size = input.travelType === "group" ? (parseInt(input.groupSize, 10) || 1) : 1;
	trip.u_destination_package = input.destinationPackage || "silver";
	trip.u_preferred_language = input.preferredLanguage || "";
	trip.u_emergency_contact_name = emergencyName;
	trip.u_emergency_contact_phone = emergencyPhone;
	trip.u_buddy = buddyId;
	trip.weather = input.weatherSummary || "";

	var newTripId = trip.insert();
	if (!newTripId) {
		data.error = "We were unable to submit your trip request. Please try again later.";
		return;
	}

	// Notify both the traveler and the selected buddy that the request was created.
	gs.eventQueue("x_travel_buddy_app.trip_request.created", trip, gs.getUserID(), buddyId);

	data.number = trip.getValue("number") || newTripId;
	data.submitted = true;
})(data, input);
